CREATE TABLE IF NOT EXISTS public.resume_invites (id UUID NOT NULL DEFAULT gen_random_uuid() PRIMARY KEY, candidate_name TEXT, recipient_email TEXT NOT NULL, subject TEXT, sender_name TEXT, sender_user_id UUID, status TEXT NOT NULL DEFAULT 'pending', resend_message_id TEXT, error_message TEXT, metadata JSONB DEFAULT '{}'::jsonb, sent_at TIMESTAMPTZ, accepted_at TIMESTAMPTZ, created_at TIMESTAMPTZ NOT NULL DEFAULT now(), updated_at TIMESTAMPTZ NOT NULL DEFAULT now(), CONSTRAINT resume_invites_status_check CHECK (status IN ('pending','sent','failed','accepted'))); CREATE INDEX IF NOT EXISTS idx_resume_invites_email ON public.resume_invites (lower(recipient_email)); CREATE INDEX IF NOT EXISTS idx_resume_invites_status ON public.resume_invites (status); CREATE INDEX IF NOT EXISTS idx_resume_invites_created_at ON public.resume_invites (created_at DESC); ALTER TABLE public.resume_invites ENABLE ROW LEVEL SECURITY; DROP POLICY IF EXISTS "Admins manage resume invites" ON public.resume_invites; CREATE POLICY "Admins manage resume invites" ON public.resume_invites FOR ALL TO authenticated USING (public.has_role(auth.uid(), 'admin'::app_role) OR public.has_role(auth.uid(), 'owner'::app_role)) WITH CHECK (public.has_role(auth.uid(), 'admin'::app_role) OR public.has_role(auth.uid(), 'owner'::app_role)); DROP TRIGGER IF EXISTS trg_resume_invites_updated_at ON public.resume_invites; CREATE TRIGGER trg_resume_invites_updated_at BEFORE UPDATE ON public.resume_invites FOR EACH ROW EXECUTE FUNCTION public.update_updated_at_column(); CREATE OR REPLACE FUNCTION public.mark_resume_invites_accepted() RETURNS TRIGGER LANGUAGE plpgsql SECURITY DEFINER SET search_path = public AS $func$ BEGIN IF NEW.email IS NOT NULL THEN UPDATE public.resume_invites SET status = 'accepted', accepted_at = COALESCE(accepted_at, now()), updated_at = now() WHERE lower(recipient_email) = lower(NEW.email) AND status <> 'accepted'; END IF; RETURN NEW; END; $func$; DROP TRIGGER IF EXISTS trg_profiles_mark_resume_invites_accepted ON public.profiles; CREATE TRIGGER trg_profiles_mark_resume_invites_accepted AFTER INSERT OR UPDATE OF email ON public.profiles FOR EACH ROW EXECUTE FUNCTION public.mark_resume_invites_accepted();